mapper.select:
SELECT entry_uid AS entryUid, region, phonetic, audio_resource_uid AS audioResourceUid, sort_order AS sortOrder FROM dictionary_pronunciation WHERE entry_uid IN
#{entryUid}
ORDER BY sort_order ASC, id ASC

SELECT sense_uid AS senseUid, entry_uid AS entryUid, part_of_speech AS partOfSpeech, definition_en AS definitionEn, definition_zh AS definitionZh, grammar_label AS grammarLabel, register_label AS registerLabel, sort_order AS sortOrder FROM dictionary_sense WHERE entry_uid IN
#{entryUid}
ORDER BY sort_order ASC, id ASC

SELECT example_uid AS exampleUid, sense_uid AS senseUid, entry_uid AS entryUid, text_en AS textEn, text_zh AS textZh, source, sort_order AS sortOrder FROM dictionary_example WHERE entry_uid IN
#{entryUid}
ORDER BY sort_order ASC, id ASC LIMIT 20

SELECT phrase_uid AS phraseUid, entry_uid AS entryUid, phrase_text AS phraseText, definition_en AS definitionEn, definition_zh AS definitionZh, sort_order AS sortOrder FROM dictionary_phrase WHERE entry_uid IN
#{entryUid}
ORDER BY sort_order ASC, id ASC LIMIT 20
